def selection_sort(a):
    n = len(a)
    for i in range(n - 1):
        m = i
        for j in range(i + 1, n):
            if a[j][0] < a[m][0]:
                m = j
        a[i], a[m] = a[m], a[i]

recs = [(2, "x"), (2, "y"), (1, "z")]
selection_sort(recs)
print(" ".join(r[1] for r in recs))

