def eval_postfix(expr):
    st = []
    for tok in expr.split():
        if tok in "+-*":
            right = st.pop()
            left = st.pop()
            if tok == "+":
                st.append(left + right)
            elif tok == "-":
                st.append(left - right)
            else:
                st.append(left * right)
        else:
            st.append(int(tok))
    return st.pop()

print(eval_postfix("6 2 3 + * 4 -"))

