def balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    st = []
    for ch in s:
        if ch in "([{":
            st.append(ch)
        elif not st or st.pop() != pairs[ch]:
            return False
    return not st

class Q2:
    def __init__(self):
        self.inb, self.out = [], []

    def enq(self, x):
        self.inb.append(x)

    def deq(self):
        if not self.out:
            while self.inb:
                self.out.append(self.inb.pop())
        return self.out.pop()

q = Q2()
for x in (1, 2, 3):
    q.enq(x)
a = q.deq()
q.enq(4)
b = q.deq()
c = q.deq()
