from collections import deque

g = {"A": ["C"], "B": ["C", "D"], "C": ["E"],
     "D": ["E"], "E": [], "F": ["D"]}
indeg = {v: 0 for v in g}
for u in g:
    for v in g[u]:
        indeg[v] += 1
q = deque(v for v in g if indeg[v] == 0)
out = []
while q:
    u = q.popleft()
    out.append(u)
    for v in g[u]:
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)
print(" ".join(out))
